// Traegt die 12 Vorgaenge ein, deren golietz.de-Post nachtraeglich mit echtem Satire-Content
// aktualisiert werden soll (siehe P7-Wettlauf-Fix 2026-07-26). Erst ausfuehren, wenn P4 fuer
// diese Zeilen tatsaechlich contentStage=content_generated/content_posted erreicht hat -
// sonst wird die Zeile hier uebersprungen (kein Fehler, einfach kein Update).
const TARGETS = [
  { vorgangKey: 'vol_10604', wordpressPostId: 2268 },
  { vorgangKey: 'vol_10584', wordpressPostId: 2261 },
  { vorgangKey: 'vol_10607', wordpressPostId: 2269 },
  { vorgangKey: 'vol_10595', wordpressPostId: 2265 },
  { vorgangKey: 'vol_10580', wordpressPostId: 2257 },
  { vorgangKey: 'vol_10579', wordpressPostId: 2256 },
  { vorgangKey: 'vol_10582', wordpressPostId: 2259 },
  { vorgangKey: 'vol_10598', wordpressPostId: 2270 },
  { vorgangKey: 'vol_10593', wordpressPostId: 2264 },
  { vorgangKey: 'vol_10587', wordpressPostId: 2262 },
  { vorgangKey: 'vol_10597', wordpressPostId: 2266 },
  { vorgangKey: 'vol_10601', wordpressPostId: 2267 }
];

if (!TARGETS.length) {
  throw new Error('[WP-Nachtragen] TARGETS befuellen.');
}

return TARGETS.map(t => ({ json: t }));

// Prueft, ob P4 fuer diese Zeile inzwischen echten Content erzeugt hat. Wenn nicht:
// ueberspringen (kein Update, kein Fehler) - der Nutzer kann dieses Tool spaeter erneut
// ausfuehren, sobald P4 gelaufen ist.
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
const row = $input.item.json;
const websiteHeadline = safeStr(row.websiteHeadline);
const websiteArticle = safeStr(row.websiteArticle);
const contentReady = websiteHeadline.length > 0 && websiteArticle.length > 20;
return {
  json: {
    ...row,
    _contentReady: contentReady,
    wordpressTitle: websiteHeadline,
    wordpressContent: websiteArticle
  }
};
